#!/usr/bin/env node
// Action pin parity. Dependabot keeps the pins in this repo's own .github/workflows/ current, but it cannot
// see what we ship: workflow templates (*.yml.tmpl), stack CI fragments (plugins/*/ci/*.yml) and CI lines
// generated by scaffold scripts (*.mjs).
// This repo's workflows are the source of truth. Actions that only shipped content uses are listed in
// .github/workflows/action-pins.yml, a registry workflow that never runs, so Dependabot updates them too.
//
//   node scripts/pins.mjs     rewrite shipped pins to match .github/workflows/ (part of npm run sync)
//   checkPins(root)           drift report used by validate.mjs

import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

// `uses: owner/repo[/path]@<40-hex sha> # <version>`, in YAML or inside a JS string.
const PIN_RE = /(uses:\s*["']?)([A-Za-z0-9_.-]+\/[^"'\s@#]+)@([0-9a-f]{40})(["']?)(?:(\s*#\s*)([^\s"'`]+))?/g;

/** The action repository a `uses:` ref belongs to: `actions/cache/save` → `actions/cache`. */
const actionRepo = (ref) => ref.split("/").slice(0, 2).join("/").toLowerCase();
const posix = (p) => p.replace(/\\/g, "/");

function listFiles(root) {
  const source = [];
  const wf = join(root, ".github", "workflows");
  if (existsSync(wf)) for (const f of readdirSync(wf)) if (/\.ya?ml$/.test(f)) source.push(join(".github", "workflows", f));
  const shipped = [];
  const visit = (rel) => {
    for (const e of readdirSync(join(root, rel), { withFileTypes: true })) {
      const child = join(rel, e.name);
      if (e.isDirectory()) {
        if (e.name !== "node_modules") visit(child);
      } else if ((/\.ya?ml\.tmpl$/.test(e.name) && /[\\/]workflows[\\/]/.test(child)) || (/\.ya?ml$/.test(e.name) && /^plugins[\\/][^\\/]+[\\/]ci[\\/]/.test(child)) || (e.name.endsWith(".mjs") && !e.name.endsWith(".test.mjs")))
        shipped.push(child);
    }
  };
  if (existsSync(join(root, "plugins"))) visit("plugins");
  return { source, shipped };
}

function pinsOf(text) {
  const out = [];
  text.split(/\r?\n/).forEach((line, i) => {
    for (const m of line.matchAll(PIN_RE)) out.push({ line: i + 1, repo: actionRepo(m[2]), sha: m[3], version: m[6] ?? "" });
  });
  return out;
}

/** action repo → { sha, version, from } taken from this repo's workflows. Conflicting pins are errors. */
export function sourcePins(root) {
  const pins = new Map();
  const errors = [];
  for (const rel of listFiles(root).source) {
    for (const p of pinsOf(readFileSync(join(root, rel), "utf8"))) {
      const where = `${posix(rel)}:${p.line}`;
      const seen = pins.get(p.repo);
      if (!seen) pins.set(p.repo, { sha: p.sha, version: p.version, from: where });
      else if (seen.sha !== p.sha)
        errors.push(`${where}: ${p.repo} is pinned to ${p.sha.slice(0, 12)} but ${seen.from} pins ${seen.sha.slice(0, 12)}; use one pin per action`);
    }
  }
  return { pins, errors };
}

export function checkPins(root) {
  const { pins, errors } = sourcePins(root);
  for (const rel of listFiles(root).shipped) {
    for (const p of pinsOf(readFileSync(join(root, rel), "utf8"))) {
      const want = pins.get(p.repo);
      if (!want)
        errors.push(`${posix(rel)}:${p.line}: ${p.repo} is not pinned in .github/workflows/; add it to action-pins.yml so Dependabot keeps it current`);
      else if (want.sha !== p.sha)
        errors.push(`${posix(rel)}:${p.line}: ${p.repo} pin ${p.sha.slice(0, 12)} differs from ${want.from} (${want.sha.slice(0, 12)} ${want.version}); run npm run sync`);
    }
  }
  return errors;
}

export function syncPins(root) {
  const { pins } = sourcePins(root);
  const written = [];
  for (const rel of listFiles(root).shipped) {
    const path = join(root, rel);
    const text = readFileSync(path, "utf8");
    const next = text.replace(PIN_RE, (all, pre, ref, sha, quote, hash) => {
      const want = pins.get(actionRepo(ref));
      if (!want || want.sha === sha) return all;
      return `${pre}${ref}@${want.sha}${quote}${want.version ? `${hash ?? " # "}${want.version}` : ""}`;
    });
    if (next !== text) {
      writeFileSync(path, next);
      written.push(posix(rel));
    }
  }
  return written;
}

const isMain = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const root = join(dirname(fileURLToPath(import.meta.url)), "..");
  for (const f of syncPins(root)) console.log(`pinned ${f}`);
}
